SELECT *
FROM inventory
WHERE store_id IN (1, 3, 4, 6) AND store_id = 5 AND product_id IN (7, 10);

select *
from accounts
where status in ('CLOSED', 'FROZEN') and customer_id = 12 and customer_id in (2, 37);

SELECT stores.id, stores.opened_date
FROM stores
WHERE stores.opened_date < '2023-04-01' AND stores.id IN (SELECT store_id FROM orders WHERE channel IN ('web', 'store'));

SELECT id, balance, DENSE_RANK() OVER (ORDER BY balance) dense_rnk
FROM accounts
ORDER BY id DESC;

SELECT id, quantity, ROW_NUMBER() OVER (ORDER BY quantity, id) AS rn
FROM order_items
ORDER BY quantity DESC;

select *
from payments
where amount > 910;

select *
from accounts
where status = 'OPEN';

SELECT *
FROM orders
WHERE channel = 'web' AND customer_id = 7;

SELECT id, city
FROM customers
WHERE segment IN ('Corporate', 'SMB', 'Consumer') OR is_active;

SELECT *, COALESCE(browser, 'N/A') AS browser_filled, YEAR(started_at) AS started_at_year
FROM sessions
WHERE browser = 'Safari' AND country = 'SG';

SELECT *, revenue * units AS revenue_per_unit
FROM store_sales
ORDER BY sale_date;

SELECT status, MAX(start_date) AS last_start_date, MAX(monthly_fee) AS max_monthly_fee
FROM subscriptions
GROUP BY status;

SELECT city, COUNT(DISTINCT rating) AS unique_citys
FROM suppliers
GROUP BY city;

SELECT brand, ROUND(AVG(price), 2) avg_price, SORT_ARRAY(COLLECT_SET(category)) category_list
FROM products
GROUP BY brand;

SELECT txn_type, MIN(amount) AS min_amount
FROM transactions
GROUP BY txn_type;

SELECT store_id, COUNT(DISTINCT revenue) unique_products
FROM store_sales
GROUP BY 1;

SELECT is_remote, SORT_ARRAY(COLLECT_SET(level)) AS level_list, SORT_ARRAY(COLLECT_SET(job_title)) AS job_title_list
FROM employees
GROUP BY is_remote;

SELECT country, city, ROUND(AVG(rating), 2) AS avg_rating
FROM suppliers
GROUP BY country, city;

SELECT store_id, product_id, MAX(quantity) AS max_quantity
FROM inventory
GROUP BY store_id, product_id;

SELECT region, city, SORT_ARRAY(COLLECT_SET(city)) AS city_list
FROM stores
GROUP BY region, city;

SELECT product_id, store_id, SUM(units) total_units
FROM store_sales
GROUP BY product_id, store_id;

SELECT status, COUNT(*) AS subscription_count
FROM subscriptions
GROUP BY status;

SELECT store_id, SUM(quantity) total_quantity, MIN(last_restock) first_last_restock
FROM inventory
GROUP BY store_id;

SELECT level, AVG(salary) AS avg_salary
FROM employees
GROUP BY level;

with base as (
    select
        *,
        initcap(trim(region)) as region_title,
        coalesce(region, 'N/A') as resolved_region
    from stores
    where opened_date > date '2023-08-15'
)
select *
from (
    select
        region,
        city,
        sqft
    from base
) src
pivot (
    max(sqft) as total
    for city in ('Chiang Mai' as chiang_mai, 'Tokyo' as tokyo)
);
